var tribonacci = function(n) {
    // Base cases: T0=0, T1=1, T2=1
    if (n === 0) return 0;
    if (n <= 2) return 1;

    // Use three variables to avoid storing the full array
    let prev2 = 0; // T(n-3)
    let prev1 = 1; // T(n-2)
    let curr = 1;  // T(n-1)

    // Compute from T3 up to Tn
    for (let i = 3; i <= n; i++) {
        const next = prev2 + prev1 + curr;
        prev2 = prev1;
        prev1 = curr;
        curr = next;
    }

    return curr;
};

